#include <pthread.h>
#include <stdio.h>

int main() {
    pthread_mutexattr_t attr;
    int result = pthread_mutexattr_init(&attr);
    if (result == 0) {
        printf("Mutex attributes initialized successfully.\n");
    } else {
        printf("Failed to initialize mutex attributes.\n");
    }
    pthread_mutexattr_destroy(&attr);  // Clean up the attributes
    return 0;
}
